"""Apply the shared reading experience without changing the research record."""
from pathlib import Path
import re,json,html
R=Path(__file__).resolve().parents[1]
D=json.loads((R/'assets/research-data.json').read_text())
E=lambda s:html.escape(str(s),quote=True)
init='''<script>(function(){try{var t=localStorage.getItem('sir-theme');if(t==='dark'||t==='light')document.documentElement.dataset.theme=t}catch(e){}})();</script>'''
for p in R.rglob('*.html'):
 t=p.read_text();m=re.search(r'data-base="([^"]*)"',t)
 if not m:continue
 b=m[1]
 t=re.sub(r'<div class="reading-progress" aria-hidden="true"><span></span></div>','',t)
 t=t.replace('content="dark"','content="dark light"')
 if init not in t:t=t.replace('<link rel="stylesheet"',init+'<link rel="stylesheet"',1)
 t=re.sub(r'<header class="mast">.*?</header>',f'''<header class="mast"><a class="top-brand" href="{b}index.html" aria-label="The SIR Files home"><span class="brand-symbol">S<span>↗</span></span>THE SIR <b>FILES</b></a><nav class="top-nav" aria-label="Explore"><a href="{b}state-files/">State files</a><a href="{b}claims/">Check a claim</a><a href="{b}evidence/">The sources</a></nav><div class="mast-right"><button data-theme aria-label="Switch colour theme">◐ <span>Theme</span></button><button data-search-open aria-label="Search all pages">⌕ <span>Search</span><kbd>⌘K</kbd></button><button class="mobile-menu" data-menu aria-label="Open site menu" aria-expanded="false">☰</button></div></header><div class="reading-progress" aria-hidden="true"><span></span></div>''',t,flags=re.S)
 t=t.replace('A DOCUMENTARY INVESTIGATION','FOLLOW THE RECORD')
 t=t.replace('>The publication<','>Find your way<').replace('>Open jurisdiction directory (36)<','>All 36 states &amp; Union Territories<')
 t=t.replace('>Latest Research <','>Latest review <').replace('>Claims Register <','>Check a claim <').replace('>Full Audit <','>What we checked <')
 if 'class="reading-tools"' not in t and p!=R/'index.html':
  t=t.replace('<main id="main" class="container">','<main id="main" class="container"><div class="reading-tools"><a href="'+b+'index.html">← Back to the story</a><button data-save>＋ Save for later</button><button data-share>↗ Share this page</button></div>',1)
 if p==R/'index.html':
  states=''.join(f'''<a class="state-card" data-state="{E(j['name'].lower())}" data-scope="{'detailed' if j['depth']!='Reference file' else 'reference'}" href="state-files/{j['slug']}/"><span class="count">{'Closer look' if j['depth']!='Reference file' else 'Reference file'}</span><h3>{E(j['name'])}</h3><p>{E(j['deck'])}</p><span class="card-foot">Read the file <span>↗</span></span></a>''' for j in sorted(D['jurisdictions'],key=lambda j:(j['depth']=='Reference file',j['name'])))
  claims=''.join(f'''<details class="claim-preview"><summary><span class="status">{E(c['status'])}</span><h3>{E(c['claim'])}</h3><span class="detail-prompt">See what supports this +</span></summary><div class="claim-answer"><p>{E(c['limitation'])}</p><a href="claims/#{E(c['id'])}">Read the evidence and next steps →</a></div></details>''' for c in [D['claims'][0],D['claims'][1],next(c for c in D['claims'] if c['id']=='NAT-01')])
  timeline=''.join(f'<details class="timeline-item"{ " open" if i==3 else ""}><summary><span>{E(x[0])}</span><strong>{E(x[1])}</strong><b>+</b></summary><p>{E(x[2])}</p></details>' for i,x in enumerate(D['chronology']))
  main=f'''<main id="main" class="container home"><section class="hero"><div class="hero-text"><div class="eyebrow"><span class="signal"></span> INDEPENDENT RESEARCH · INDIA’S ELECTORAL ROLLS</div><h1>A name on a list.<br><em>A voice in a democracy.</em></h1><p>Who gets counted? Who gets left out? And what does the record actually show? Follow the Special Intensive Revision of India’s electoral rolls, one question at a time.</p><div class="button-row"><a class="button" href="#start">Find your way in <span>↓</span></a><a class="button outline" href="research/">Read the latest review ↗</a></div><p class="hero-note">New to SIR? It’s the process of preparing electoral rolls afresh. The details matter—and so do the people behind them.</p></div><div class="hero-art" aria-label="Illustration of a voter entry and its supporting records" role="img"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><span class="orbit-label label-one">THE PERSON</span><span class="orbit-label label-two">THE PROCESS</span><div class="record-card"><span class="record-kicker">BEHIND EVERY ENTRY</span><div class="entry-symbol">↗</div><strong>More than<br>a number.</strong><div class="record-lines"><i></i><i></i><i></i></div><span class="record-bottom">A name. A decision. A right.</span></div><span class="art-footnote">FOLLOW THE RECORD / ASK THE NEXT QUESTION</span></div></section>
<div class="edition"><span><i class="signal"></i> Reviewed 17 October 2026</span><span>Sources checked through 16 October · This is a dated archive</span><a href="audit/">What we checked ↗</a></div>
<section id="start" class="section-block"><div class="section-head"><div><span class="eyebrow">01 / START WHERE YOU ARE</span><h2>You don’t have to read everything<br>to understand what’s at stake.</h2></div><p>Pick the question that brought you here.</p></div><div class="entry-grid"><a class="entry-card" href="history/"><span>01 <b>↗</b></span><h3>“What is SIR, anyway?”</h3><p>The backstory, the turning points, and why this became a national debate.</p><strong>Start with the story →</strong></a><a class="entry-card" href="#places"><span>02 <b>↘</b></span><h3>“What happened in my state?”</h3><p>Find the local record, the decisions we can trace, and the questions still open.</p><strong>Find your state →</strong></a><a class="entry-card" href="#claims"><span>03 <b>↘</b></span><h3>“Can I trust that claim?”</h3><p>Look past the headline. See the source, its limits, and what would change the answer.</p><strong>Check the evidence →</strong></a></div></section>
<section id="claims" class="section-block"><div class="section-head"><div><span class="eyebrow">02 / A CLOSER LOOK</span><h2>A claim is only the beginning.</h2></div><a class="more" href="claims/">All 20 claims →</a></div><p class="section-intro">Open a question. See where the evidence holds—and where it stops.</p><div class="claim-previews">{claims}</div><div class="principle"><span>KEEP THIS DISTINCTION IN MIND</span><p>A missing name on a draft roll is not automatically a final exclusion. A balanced spreadsheet doesn’t tell us whether every decision was fair.</p><a href="national/">Why the difference matters ↗</a></div></section>
<section id="places" class="section-block"><div class="section-head"><div><span class="eyebrow">03 / THE STATE FILES</span><h2>One country.<br>Different stories.</h2></div><p>36 jurisdictions. Eight developed analyses.<br>28 reference files with work still to do.</p></div><div class="filterbar"><label>Find a state or Union Territory<input id="state-filter" type="search" placeholder="Try Goa, Bihar, Maharashtra…"></label><label>Show<select id="state-scope"><option value="detailed">The eight developed files</option><option value="all">All 36 jurisdictions</option><option value="reference">Reference files</option></select></label><span id="state-count" aria-live="polite">36 jurisdictions</span></div><div class="state-grid">{states}</div><p class="empty-state hidden" id="state-empty">No match yet. Try another state name or choose all jurisdictions.</p></section>
<section class="section-block timeline-section"><div><span class="eyebrow">04 / HOW WE GOT HERE</span><h2>The story didn’t<br>start yesterday.</h2><p>Orders, court rulings, changing timetables. Open a moment to see what changed.</p><a class="more" href="history/">Read the full history →</a></div><div class="timeline">{timeline}</div></section>
<section class="closing"><span class="eyebrow">CURIOSITY IS A GOOD START. THE RECORD TAKES YOU FURTHER.</span><h2>Don’t just take<br>our word for it.</h2><p>Read the documents. Challenge the conclusions. See the corrections. The gaps are part of the story, too.</p><div class="button-row"><a class="button" href="evidence/">Open the source library ↗</a><a class="button outline" href="investigations/">What we still don’t know →</a></div></section></main>'''
  t=re.sub(r'<main id="main" class="container".*?</main>',lambda _:main,t,flags=re.S)
 p.write_text(t)
print('Updated shared navigation and homepage')
